select.title:
@concat(
    string(item()?['CampaignNumber']),
    ' - [',
    coalesce(item()?['Subject'], '[No subject]'),
    '] | From: ',
    coalesce(item()?['SenderFromAddress'], '[Unknown sender]'),
    ' | ',
    string(item()?['TotalEmails']),
    if(equals(item()?['TotalEmails'], 1), ' email', ' emails'),
    ' | ',
    string(item()?['UniqueRecipients']),
    if(equals(item()?['UniqueRecipients'], 1), ' recipient', ' recipients')
)

body.messageBody:
{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.4",
  "msteams": {
    "width": "Full"
  },
  "body": [
    {
      "type": "TextBlock",
      "text": "Quarantined Campaign Review",
      "weight": "Bolder",
      "size": "Large",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "@{if(parameters('TestMode'), 'TEST MODE — showing quarantined messages from the configured test sender.', 'PRODUCTION MODE — showing quarantined inbound spoofing campaigns that failed DMARC.')}",
      "wrap": true,
      "color": "@{if(parameters('TestMode'), 'Warning', 'Default')}"
    },
    {
      "type": "TextBlock",
      "text": "@{if(parameters('AutomatedRelease'), 'Selected campaigns will be released automatically.', 'A PowerShell release command will be generated for the selected campaigns.')}",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "The Advanced Hunting preview query was posted immediately before this card.",
      "wrap": true,
      "isSubtle": true,
      "spacing": "Small"
    },
    {
      "type": "Input.ChoiceSet",
      "id": "selectedCampaigns",
      "label": "Select the campaigns to release",
      "isMultiSelect": true,
      "style": "expanded",
      "wrap": true,
      "isRequired": true,
      "errorMessage": "Select at least one campaign.",
      "choices": @{body('Select_Campaign_Choices')}
    },
    {
      "type": "Input.Text",
      "id": "analystNotes",
      "label": "Analyst notes",
      "isMultiline": true,
      "isRequired": false,
      "placeholder": "Optional reason or investigation notes"
    }
  ],
  "actions": [
    {
      "type": "Action.Submit",
      "title": "@{if(parameters('AutomatedRelease'), 'Release Selected Campaigns', 'Generate Release Command')}",
      "associatedInputs": "auto",
      "data": {
        "decision": "approve"
      }
    },
    {
      "type": "Action.Submit",
      "title": "Skip",
      "associatedInputs": "none",
      "data": {
        "decision": "skip"
      }
    }
  ]
}

inputs.value:
@if(
    empty(
        outputs('Find_Campaign_Sender_in_Entra')?['body']?['value']
    ),
    'Unknown department',
    if(
        empty(
            first(
                outputs('Find_Campaign_Sender_in_Entra')?['body']?['value']
            )?['department']
        ),
        'Unknown department',
        first(
            outputs('Find_Campaign_Sender_in_Entra')?['body']?['value']
        )?['department']
    )
)

