{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.4",
  "msteams": {
    "width": "Full"
  },
  "body": [
    {
      "type": "TextBlock",
      "text": "DMARC Ticket Submitted",
      "weight": "Bolder",
      "size": "Large",
      "wrap": true,
      "color": "Good"
    },
    {
      "type": "TextBlock",
      "text": "@{if(parameters('ServiceNowTestMode'), 'TEST SERVICENOW', 'PRODUCTION SERVICENOW')}",
      "weight": "Bolder",
      "color": "@{if(parameters('ServiceNowTestMode'), 'Warning', 'Default')}",
      "wrap": true
    },
    {
      "type": "FactSet",
      "facts": [
        {
          "title": "Campaign:",
          "value": "@{string(items('For_each_Selected_Campaign')?['CampaignNumber'])}"
        },
        {
          "title": "Quantity:",
          "value": "1"
        },
        {
          "title": "Rush request:",
          "value": "False"
        }
      ]
    },
    {
      "type": "TextBlock",
      "text": "Service/Vendor",
      "weight": "Bolder",
      "spacing": "Medium",
      "separator": true
    },
    {
      "type": "TextBlock",
      "text": "@{outputs('Campaign_Vendor')}",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "Notes",
      "weight": "Bolder",
      "spacing": "Medium",
      "separator": true
    },
    {
      "type": "TextBlock",
      "text": "@{outputs('ServiceNow_Ticket_Notes')}",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "Details",
      "weight": "Bolder",
      "spacing": "Medium",
      "separator": true
    },
    {
      "type": "TextBlock",
      "text": "@{parameters('DetailMessage')}",
      "wrap": true
    }
  ]
}

{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.4",
  "msteams": {
    "width": "Full"
  },
  "body": [
    {
      "type": "TextBlock",
      "text": "Quarantine Release Complete",
      "weight": "Bolder",
      "size": "Medium"
    },
    {
      "type": "TextBlock",
      "text": "All selected messages were successfully released from quarantine and verified.",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "**Released:** @{body('Parse_Releases_Output')?['SuccessfulCount']}",
      "wrap": true
    }
  ]
}

{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.4",
  "msteams": {
    "width": "Full"
  },
  "body": [
    {
      "type": "TextBlock",
      "text": "Quarantine Release Incomplete",
      "weight": "Bolder",
      "size": "Medium"
    },
    {
      "type": "TextBlock",
      "text": "One or more selected messages could not be released or verified.",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "**Released:** @{body('Parse_Releases_Output')?['SuccessfulCount']}\n\n**Failed:** @{body('Parse_Releases_Output')?['FailedCount']}",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "**Failed Message IDs**",
      "weight": "Bolder",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "@{join(body('Parse_Releases_Output')?['FailedMessageIds'], decodeUriComponent('%0A'))}",
      "wrap": true
    }
  ]
}

inputs.value:
@concat(
    decodeUriComponent('%27'),
    replace(
        replace(
            replace(
                string(item()),
                decodeUriComponent('%0D'),
                ''
            ),
            decodeUriComponent('%0A'),
            ''
        ),
        decodeUriComponent('%27'),
        concat(
            decodeUriComponent('%27'),
            decodeUriComponent('%27')
        )
    ),
    decodeUriComponent('%27')
)

