  },
  "body": [
    {
      "type": "TextBlock",
      "text": "TABL Sender Allowlist Review",
      "weight": "Bolder",
      "size": "Large",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "Select only the senders that should be added to the Tenant Allow/Block List.",
      "wrap": true
    },
    {
      "type": "Input.ChoiceSet",
      "id": "selectedSenders",
      "label": "Senders available for allowlisting",
      "isMultiSelect": true,
      "style": "expanded",
      "wrap": true,
      "isRequired": false,
      "choices": @{body('Select_Sender_Allow_Choices')}
    },
    {
      "type": "Input.Text",
      "id": "allowlistNotes",
      "label": "Analyst notes",
      "isMultiline": true,
      "isRequired": false,
      "placeholder": "Optional reason for the allowlist selection"
    }
  ],
  "actions": [
    {
      "type": "Action.Submit",
      "title": "Add Selected Senders to TaBl Allowlist",
      "data": {
        "decision": "allow"
      }
    },
    {
      "type": "Action.Submit",
      "title": "Skip",
      "data": {
        "decision": "skip"
      }
    }
  ]
}

{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.4",
  "msteams": {
    "width": "Full"
  },
  "body": [
    {
      "type": "TextBlock",
      "text": "Advanced Hunting Preview",
      "weight": "Bolder",
      "size": "Large",
      "wrap": true
    },
    {
      "type": "TextBlock",
      "text": "Copy and paste this query into Microsoft Defender Advanced Hunting to preview representative emails from the detected campaigns.",
      "wrap": true
    },
    {
      "type": "Input.Text",
      "id": "advancedHuntingQuery",
      "value": "@{replace(replace(replace(replace(outputs('Compose_Preview_Query'), decodeUriComponent('%5C'), decodeUriComponent('%5C%5C')), decodeUriComponent('%22'), decodeUriComponent('%5C%22')), decodeUriComponent('%0D'), ''), decodeUriComponent('%0A'), decodeUriComponent('%5C%6E'))}",
      "isMultiline": true,
      "isRequired": false
    }
  ]
}
